<?php
$pageTitle='Grupos'; require_once __DIR__ . '/includes/header.php';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    try {
        $action=$_POST['action']??'';
        if($action==='grupo') { $id=(int)($_POST['id']??0); $name=trim($_POST['nome']??''); $color=$_POST['cor']??'#223764'; if($name===''||!preg_match('/^#[0-9A-Fa-f]{6}$/',$color)) throw new RuntimeException('Dados do grupo inválidos.'); $especial=isset($_POST['especial'])?1:0; $status=$_POST['status']==='oculto'?'oculto':'ativo'; $before=$id?history_snapshot($pdo,'grupo',$id):[]; if($id) {$pdo->prepare('UPDATE grupos SET nome=?,cor=?,especial=?,status=? WHERE id=?')->execute([$name,$color,$especial,$status,$id]);} else $pdo->prepare('INSERT INTO grupos (nome,tempo_padrao,cor,especial,status) VALUES (?,?,?,?,?)')->execute([$name,60,$color,$especial,$status]); $id=$id?:(int)$pdo->lastInsertId(); history_log($pdo,'grupo',$id,$before,history_snapshot($pdo,'grupo',$id)); }
        if($action==='subgrupo') { $id=(int)($_POST['id']??0);$group=(int)($_POST['grupo_id']??0);$name=trim($_POST['nome']??'');if(!$group||$name==='') throw new RuntimeException('Informe grupo e nome do subgrupo.'); $before=$id?history_snapshot($pdo,'subgrupo',$id):[]; if($id)$pdo->prepare('UPDATE subgrupos SET grupo_id=?,nome=?,status=? WHERE id=?')->execute([$group,$name,$_POST['status']==='oculto'?'oculto':'ativo',$id]);else $pdo->prepare('INSERT INTO subgrupos (grupo_id,nome) VALUES (?,?)')->execute([$group,$name]); $id=$id?:(int)$pdo->lastInsertId(); history_log($pdo,'subgrupo',$id,$before,history_snapshot($pdo,'subgrupo',$id)); }
        flash('success','Cadastro salvo.'); redirect('grupos.php');
    } catch(Throwable $e) { flash('error',$e->getMessage()); }
}
if(isset($_GET['toggle'],$_GET['type'])) { $table=$_GET['type']==='subgrupo'?'subgrupos':'grupos'; $entity=$_GET['type']==='subgrupo'?'subgrupo':'grupo'; $toggleId=(int)$_GET['toggle']; $before=history_snapshot($pdo,$entity,$toggleId); $pdo->prepare("UPDATE $table SET status=IF(status='ativo','oculto','ativo') WHERE id=?")->execute([$toggleId]); history_log($pdo,$entity,$toggleId,$before,history_snapshot($pdo,$entity,$toggleId)); flash('success','Status atualizado.'); redirect('grupos.php'); }
$editGroup=['id'=>'','nome'=>'','cor'=>'#223764','especial'=>0,'status'=>'ativo']; $editSub=['id'=>'','grupo_id'=>'','nome'=>'','status'=>'ativo'];
if(isset($_GET['editar_grupo'])){$s=$pdo->prepare('SELECT * FROM grupos WHERE id=?');$s->execute([(int)$_GET['editar_grupo']]);$editGroup=$s->fetch()?:$editGroup;}
if(isset($_GET['editar_subgrupo'])){$s=$pdo->prepare('SELECT * FROM subgrupos WHERE id=?');$s->execute([(int)$_GET['editar_subgrupo']]);$editSub=$s->fetch()?:$editSub;}
$groups=$pdo->query('SELECT * FROM grupos ORDER BY nome')->fetchAll();
$subs=[];
if ($editGroup['id']) { $s=$pdo->prepare('SELECT s.*,g.nome AS grupo FROM subgrupos s JOIN grupos g ON g.id=s.grupo_id WHERE s.grupo_id=? ORDER BY s.nome'); $s->execute([$editGroup['id']]); $subs=$s->fetchAll(); }
?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Grupos</h1><p class="text-muted mb-0">Organização e identificação visual da agenda</p></div></div><div class="row g-4"><div class="col-12"><section class="app-card mb-4"><h2 class="h5 mb-3"><?= $editGroup['id']?'Editar grupo':'Novo grupo' ?></h2><form method="post"><input type="hidden" name="action" value="grupo"><input type="hidden" name="id" value="<?= e($editGroup['id']) ?>"><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Nome</label><input class="form-control" name="nome" required value="<?= e($editGroup['nome']) ?>"></div><div class="col-md-3 mb-3"><label class="form-label">Cor</label><input class="form-control form-control-color w-100" type="color" name="cor" value="<?= e($editGroup['cor']) ?>"></div><div class="col-md-3 mb-3"><label class="form-label">Status</label><select class="form-select" name="status"><option value="ativo" <?= $editGroup['status']==='ativo'?'selected':'' ?>>Ativo</option><option value="oculto" <?= $editGroup['status']==='oculto'?'selected':'' ?>>Oculto</option></select></div></div><div class="row align-items-center"><div class="col-12 mb-3"><div class="form-check"><input class="form-check-input" type="checkbox" name="especial" id="special" <?= $editGroup['especial']?'checked':'' ?>><label class="form-check-label" for="special">Grupo especial</label><button class="help-button" type="button" data-bs-toggle="popover" data-bs-trigger="focus" data-bs-placement="right" data-bs-title="Grupo especial" data-bs-content="Permite, ao criar uma reserva deste grupo, escolher entre usar o tempo padrão ou bloquear a área durante todo o dia.">?</button></div></div></div><button class="btn btn-gold"><?= $editGroup['id']?'Salvar Alterações':'Criar novo Grupo' ?></button></form></section><?php if($editGroup['id']): ?><section class="app-card"><h2 class="h5 mb-3">Subgrupos de <?= e($editGroup['nome']) ?></h2><form method="post" class="mb-4"><input type="hidden" name="action" value="subgrupo"><input type="hidden" name="grupo_id" value="<?= $editGroup['id'] ?>"><div class="mb-3"><label class="form-label">Novo subgrupo</label><input class="form-control" name="nome" required></div><button class="btn btn-gold">Adicionar subgrupo</button></form><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nome</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($subs as $sub): ?><tr><td><?= e($sub['nome']) ?></td><td><span class="badge text-bg-<?= $sub['status']==='ativo'?'success':'secondary' ?>"><?= e($sub['status']) ?></span></td><td class="text-end"><div class="group-actions"><a class="btn btn-sm btn-action btn-action-hide" href="grupos.php?type=subgrupo&toggle=<?= $sub['id'] ?>"><?= $sub['status']==='ativo'?'Ocultar':'Ativar' ?></a></div></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?></div><div class="col-12"><section class="app-card"><h2 class="h5">Grupos</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nome</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($groups as $group): ?><tr><td><span class="d-inline-block rounded-circle me-2" style="width:12px;height:12px;background:<?= e($group['cor']) ?>"></span><?= e($group['nome']) ?><?= $group['especial']?' <span class="badge text-bg-warning">Especial</span>':'' ?></td><td><span class="badge text-bg-<?= $group['status']==='ativo'?'success':'secondary' ?>"><?= e($group['status']) ?></span></td><td class="text-end"><div class="group-actions"><a class="btn btn-sm btn-action btn-action-edit" href="grupos.php?editar_grupo=<?= $group['id'] ?>">Editar</a><a class="btn btn-sm btn-action btn-action-hide" href="grupos.php?type=grupo&toggle=<?= $group['id'] ?>"><?= $group['status']==='ativo'?'Ocultar':'Ativar' ?></a></div></td></tr><?php endforeach; ?></tbody></table></div></section></div></div><script>document.querySelectorAll('[data-bs-toggle="popover"]').forEach((element) => new bootstrap.Popover(element));</script><?php require __DIR__.'/includes/footer.php';
